function ttlWithJitter(baseSeconds, pct = 0.1) {
  const delta = baseSeconds * pct;
  return Math.round(baseSeconds - delta + Math.random() * 2 * delta);
}
await redis.set("product:" + id, JSON.stringify(product), "EX", ttlWithJitter(600));

async function getProduct(id) {
  const key = "product:" + id;
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);                 // hit

  const product = await db.products.findById(id);         // miss
  if (product) await redis.set(key, JSON.stringify(product), "EX", 600);
  else await redis.set(key, "null", "EX", 30);            // short negative cache
  return product;
}

async function updateProduct(id, patch) {
  const product = await db.products.update(id, patch);    // 1) write the source of truth
  await redis.del("product:" + id);                       // 2) invalidate
  return product;
}

