// Namespace versioning: invalidate all catalog entries in O(1)
async function catalogKey(suffix) {
  const v = (await redis.get("catalog:version")) ?? "0";
  return "catalog:v" + v + ":" + suffix;
}
await redis.set(await catalogKey("product:42"), json, "EX", 3600);
await redis.incr("catalog:version");  // after a bulk import: every old key is now unreachable

// In-process single flight: concurrent misses for the same key share one promise
const inflight = new Map();

async function cached(key, ttl, loader) {
  const hit = await redis.get(key);
  if (hit) return JSON.parse(hit);
  if (inflight.has(key)) return inflight.get(key);

  const p = (async () => {
    try {
      const value = await loader();
      await redis.set(key, JSON.stringify(value), "EX", ttl);
      return value;
    } finally {
      inflight.delete(key);
    }
  })();
  inflight.set(key, p);
  return p;
}

