async function createSession(userId) {
  const id = crypto.randomBytes(32).toString("base64url");
  await redis.multi()
    .hset("sess:" + id, { userId, createdAt: Date.now() })
    .expire("sess:" + id, 1800)                   // 30 min idle timeout
    .sadd("user:" + userId + ":sessions", id)
    .exec();
  return id;
}

async function logoutEverywhere(userId) {
  const ids = await redis.smembers("user:" + userId + ":sessions");
  const pipe = redis.pipeline();
  for (const id of ids) pipe.del("sess:" + id);
  pipe.del("user:" + userId + ":sessions");
  await pipe.exec();
}

// Sliding window log with a sorted set (atomic via MULTI)
async function allow(userId, limit = 100, windowMs = 60_000) {
  const key = "rl:" + userId;
  const now = Date.now();
  const [, [, count]] = await redis.multi()
    .zremrangebyscore(key, 0, now - windowMs)
    .zcard(key)
    .exec();
  if (count >= limit) return false;
  await redis.multi()
    .zadd(key, now, now + ":" + crypto.randomUUID())
    .pexpire(key, windowMs)
    .exec();
  return true; // small race between the two MULTI blocks: use one Lua script for strictness
}

