// Check-and-set with WATCH: transfer credits only if balance is sufficient
async function spend(userId, amount) {
  const key = "credits:" + userId;
  for (let attempt = 0; attempt < 5; attempt++) {
    await redis.watch(key);
    const balance = Number(await redis.get(key) ?? 0);
    if (balance < amount) { await redis.unwatch(); return false; }
    const res = await redis.multi().decrby(key, amount).exec();
    if (res !== null) return true;            // committed
  }                                            // null = key changed, retry
  throw new Error("too much contention");
}

// Atomic "decrement stock if available" with a Lua script (ioredis)
redis.defineCommand("reserveStock", {
  numberOfKeys: 1,
  lua: `
    local stock = tonumber(redis.call("GET", KEYS[1]) or "0")
    local qty = tonumber(ARGV[1])
    if stock < qty then return -1 end
    return redis.call("DECRBY", KEYS[1], qty)
  `,
});
